import React, { useEffect, useState } from 'react';
import '../styles'; // import CSS riêng
import { fetchDashboardData } from '../services/api';

const StatCard = ({ title, value }) => (
  <div className="stat-card">
    <p className="stat-title">{title}</p>
    <p className="stat-value">{value}</p>
  </div>
);

const Dashboard = () => {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetchDashboardData().then(setData);
  }, []);

  if (!data) return <p>Loading...</p>;

  return (
    <div className="dashboard-container">
      <div className="stat-grid">
        <StatCard title="Tổng Leads" value={data.totalLeads} />
        <StatCard title="Tổng Landing Page" value={data.totalLandingPages} />
        <StatCard title="Tỷ lệ chuyển đổi" value={`${(data.conversionRate*100).toFixed(1)}%`} />
      </div>
      {/* Các component chart, recent activity... */}
    </div>
  );
};

export default Dashboard;
